const leads = $input.all();
const now = new Date();

return leads.map(lead => {
  const lastContact = new Date(lead.json.lastContactDate || lead.json.createdAt);
  const daysSince = Math.floor((now - lastContact) / (1000 * 60 * 60 * 24));

  let action = null;
  let channel = lead.json.languagePreference === 'AR' ? 'WhatsApp' : 'Email';

  // Day 0: Welcome (already sent by Workflow 01)
  // Day 1: Value-add content
  if (daysSince === 1) {
    action = 'SEND_CONTENT';
  }
  // Day 3: Social proof
  else if (daysSince === 3) {
    action = 'SEND_SOCIAL_PROOF';
  }
  // Day 7: Scarcity / urgency
  else if (daysSince === 7) {
    action = 'SEND_URGENCY';
  }
  // Day 14: Re-engagement or consultation push
  else if (daysSince === 14) {
    action = 'SEND_CONSULTATION';
  }
  // Day 21: Final nudge
  else if (daysSince === 21) {
    action = 'SEND_FINAL';
  }

  return {
    json: {
      ...lead.json,
      daysSinceContact: daysSince,
      nextAction: action,
      channel: channel,
      processedAt: now.toISOString()
    }
  };
}).filter(l => l.json.nextAction !== null);
